using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Text.Json;
using Certes;
using Certes.Acme;
using Certes.Jws;
var lines = new List<string>\(\);
string rootPem = File.ReadAllText\("D:/agsun/Documents/GitHub/TrustForge/dev/acme-lab/secrets/root_ca.crt"\);
using X509Certificate2 root = X509Certificate2.CreateFromPem\(rootPem\);
var handler = new HttpClientHandler
{
    ServerCertificateCustomValidationCallback = \(msg, cert, chain, errors\) =>
    {
        if \(cert is null\) return false;
        using X509Chain c = new\(\);
        c.ChainPolicy.TrustMode = X509ChainTrustMode.CustomRootTrust;
        c.ChainPolicy.CustomTrustStore.Add\(root\);
        c.ChainPolicy.RevocationMode = X509RevocationMode.NoCheck;
        c.ChainPolicy.VerificationFlags = X509VerificationFlags.IgnoreWrongUsage | X509VerificationFlags.IgnoreEndRevocationUnknown;
        return c.Build\(new X509Certificate2\(cert\)\);
    }
};
using HttpClient http = new\(handler\);
var directory = new Uri\("https://127.0.0.1:9000/acme/acme/directory"\);
IKey key = KeyFactory.FromPem\(File.ReadAllText\("D:/agsun/Documents/GitHub/TrustForge/dev/acme-lab/secrets/acme-account.pem"\)\);
AcmeContext ctx = new\(directory, key, new AcmeHttpClient\(directory, http\)\);
await ctx.GetDirectory\(\);
IAccountContext account = await ctx.Account\(\);
var acctRes = await account.Resource\(\);
lines.Add\("Orders URL: " + acctRes.Orders\);
JwsPayload payload = await ctx.Sign\(null, acctRes.Orders\);
string json = JsonSerializer.Serialize\(payload, new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }\);
lines.Add\("JWS: " + json\);
string prot = Encoding.UTF8.GetString\(Convert.FromBase64String\(payload.Protected.Replace\('-', '+'\).Replace\('_', '/'\).PadRight\(payload.Protected.Length + \(4 - payload.Protected.Length % 4\) % 4, '='\)\)\);
lines.Add\("Protected: " + prot\);
lines.Add\("Payload raw: '" + payload.Payload + "'"\);
using var req = new HttpRequestMessage\(HttpMethod.Post, acctRes.Orders\) { Content = new StringContent\(json, Encoding.UTF8, "application/jose+json"\) };
using var resp = await http.SendAsync\(req\);
lines.Add\("Status: " + \(int\)resp.StatusCode\);
lines.Add\("Body: " + await resp.Content.ReadAsStringAsync\(\)\);
File.WriteAllLines\("D:/agsun/Documents/GitHub/TrustForge/dev/acme-lab/tmp-probe-result.txt", lines\);
EOF
